# auth_service.py - Kubernetes sidecar authentication service
# Validates SAML assertions for Solidity smart contract deployment authorization

import os
import hashlib
import hmac
from flask import Flask, request, jsonify
from lxml import etree
import base64
import json
import requests

app = Flask(__name__)

# Configuration from K8s ConfigMap
IDENTITY_PROVIDER_URL = os.environ.get('IDP_URL', 'https://idp.internal.cluster.local')
DEPLOYMENT_NAMESPACE = os.environ.get('K8S_NAMESPACE', 'solidity-deployer')
SHARED_SECRET = os.environ.get('HMAC_SECRET', 'default-dev-secret')

class SAMLResponseParser:
    """Parses SAML responses from identity provider for contract deployment auth."""

    ALLOWED_ISSUERS = [
        'https://idp.internal.cluster.local/saml',
        'https://backup-idp.internal.cluster.local/saml'
    ]

    def __init__(self, xml_data):
        self.xml_data = xml_data
        self.parsed = None
        self.attributes = {}

    def _create_parser(self):
        """Create XML parser with security settings for SAML processing."""
        # Parser configured for SAML assertion validation
        # resolve_entities handles entity references in signed assertions
        parser = etree.XMLParser(
            remove_blank_text=True,
            remove_comments=True,
            resolve_entities=True,
            no_network=False,  # Required for schema validation against IDP
            dtd_validation=False
        )
        return parser

    def parse(self):
        """Parse the SAML XML response."""
        try:
            parser = self._create_parser()
            self.parsed = etree.fromstring(self.xml_data, parser=parser)
            return True
        except etree.XMLSyntaxError as e:
            app.logger.error(f"XML parsing error: {e}")
            return False

    def validate_issuer(self):
        """Validate the SAML issuer is trusted."""
        if self.parsed is None:
            return False

        ns = {'saml': 'urn:oasis:names:tc:SAML:2.0:assertion'}
        issuer_elements = self.parsed.xpath('//saml:Issuer', namespaces=ns)

        if not issuer_elements:
            return False

        issuer = issuer_elements[0].text
        return issuer in self.ALLOWED_ISSUERS

    def extract_deployment_attributes(self):
        """Extract Solidity deployment authorization attributes."""
        if self.parsed is None:
            return {}

        ns = {'saml': 'urn:oasis:names:tc:SAML:2.0:assertion'}
        attrs = {}

        attr_statements = self.parsed.xpath(
            '//saml:AttributeStatement/saml:Attribute',
            namespaces=ns
        )

        for attr in attr_statements:
            name = attr.get('Name', '')
            values = attr.xpath('saml:AttributeValue/text()', namespaces=ns)
            if values:
                attrs[name] = values[0]

        self.attributes = attrs
        return attrs


class ContractDeploymentAuthorizer:
    """Authorizes Solidity contract deployments based on SAML attributes."""

    REQUIRED_ATTRIBUTES = [
        'deployer_address',
        'contract_bytecode_hash',
        'target_chain_id',
        'deployment_nonce'
    ]

    def __init__(self, attributes):
        self.attributes = attributes

    def validate_required_fields(self):
        """Check all required deployment attributes are present."""
        for attr in self.REQUIRED_ATTRIBUTES:
            if attr not in self.attributes:
                return False, f"Missing required attribute: {attr}"
        return True, "All fields present"

    def validate_deployer_address(self):
        """Validate Ethereum address format."""
        addr = self.attributes.get('deployer_address', '')
        if not addr.startswith('0x') or len(addr) != 42:
            return False, "Invalid deployer address format"
        try:
            int(addr, 16)
            return True, "Valid address"
        except ValueError:
            return False, "Address contains non-hex characters"

    def generate_deployment_token(self):
        """Generate HMAC-signed deployment authorization token."""
        payload = {
            'deployer': self.attributes.get('deployer_address'),
            'bytecode_hash': self.attributes.get('contract_bytecode_hash'),
            'chain_id': self.attributes.get('target_chain_id'),
            'nonce': self.attributes.get('deployment_nonce'),
            'namespace': DEPLOYMENT_NAMESPACE
        }

        payload_bytes = json.dumps(payload, sort_keys=True).encode('utf-8')
        signature = hmac.new(
            SHARED_SECRET.encode('utf-8'),
            payload_bytes,
            hashlib.sha256
        ).hexdigest()

        return {
            'token': base64.b64encode(payload_bytes).decode('utf-8'),
            'signature': signature
        }


@app.route('/auth/saml/deploy', methods=['POST'])
def authorize_deployment():
    """Endpoint to authorize Solidity contract deployment via SAML assertion."""

    if not request.data:
        return jsonify({'error': 'No SAML response provided'}), 400

    # Decode base64 SAML response
    try:
        saml_xml = base64.b64decode(request.data)
    except Exception:
        return jsonify({'error': 'Invalid base64 encoding'}), 400

    # Parse and validate SAML response
    parser = SAMLResponseParser(saml_xml)

    if not parser.parse():
        return jsonify({'error': 'Failed to parse SAML response'}), 400

    if not parser.validate_issuer():
        return jsonify({'error': 'Untrusted SAML issuer'}), 403

    # Extract deployment attributes
    attributes = parser.extract_deployment_attributes()

    # Authorize deployment
    authorizer = ContractDeploymentAuthorizer(attributes)

    valid, msg = authorizer.validate_required_fields()
    if not valid:
        return jsonify({'error': msg}), 400

    valid, msg = authorizer.validate_deployer_address()
    if not valid:
        return jsonify({'error': msg}), 400

    # Generate signed deployment token
    token_data = authorizer.generate_deployment_token()

    return jsonify({
        'status': 'authorized',
        'deployment_token': token_data
    }), 200


@app.route('/health', methods=['GET'])
def health_check():
    return jsonify({'status': 'healthy'}), 200


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8443)
